import math
import re

# Coordinates are rounded to five decimal places; all geometric tests below
# use a tolerance substantially smaller than any intentional feature.
TOL = 0.00015
path = """
M -30.46329,17.04949 L -30.48287,18.44949
M -21.60079,15.78978 L -21.96983,15.93144
M -25.79539,15.25765 L -23.28681,21.79271
M -30.49402,19.24642 L -30.53861,22.43412
M 0.0,10.80894 L 0.0,11.73558
M 3.4641,-6.0 L 0.0,0.0
M -4.64369,11.73558 L -10.31931,11.73558 L -10.31931,5.39837
M 0.0,11.73558 L 6.9282,11.73558
M -21.34433,15.69134 L -21.60079,15.78978
M 6.9282,0.0 L 5.05759,-3.24
M 0.0,6.1025 L 0.0,9.08803
M 6.9282,4.92894 L 6.9282,1.08437
M 0.0,11.73558 L -6.7094,14.1776
M -23.92823,14.54091 L -23.79535,14.24247
M -26.69404,17.10221 L -30.46329,17.04949
M 6.9282,11.73558 L 6.9282,6.69867 L 6.9282,4.92894
M 0.0,0.0 L 0.0,6.1025
M -27.59635,24.51813 L -27.7966,24.42897
M -19.1188,15.90818 L -18.95774,15.54643
M -23.48531,13.54611 L -23.35301,13.24896
M 0.0,9.08803 L 0.0,10.80894
M 6.9282,1.08437 L 6.9282,0.0
M -23.79535,14.24247 L -23.48531,13.54611
M -30.48287,18.44949 L -30.49402,19.24642
M -10.31931,5.39837 L -10.31931,0.0
M 0.0,11.73558 L -4.64369,11.73558
M -19.69401,17.20013 L -26.69404,17.10221
M -23.92823,14.54091 L -22.13639,19.20881
M -1.75032,11.73558 L -0.94938,11.73558
M -22.57913,17.54992 L -26.29408,17.54992
M -30.53861,22.43412 L -28.52993,24.8765
M -6.7094,14.1776 L -15.97477,17.54992
M -18.95774,15.54643 L -18.54359,14.61623
M -10.31931,11.73558 L -4.12772,11.73558
M -22.04993,15.96219 L -22.27791,16.0497
M 4.49987,-4.206 L 3.4641,-6.0
M -24.59574,14.79714 L -25.14188,15.00679
M -3.17422,11.73558 L -1.75032,11.73558
M -4.12772,11.73558 L -3.17422,11.73558
M -23.92823,14.54091 L -24.59574,14.79714
M -26.29408,17.54992 L -10.31931,11.73558
M 5.05759,-3.24 L 4.49987,-4.206
M -21.96983,15.93144 L -22.04993,15.96219
M -0.94938,11.73558 L 0.0,11.73558
M -15.97477,17.54992 L -22.57913,17.54992
M -27.7966,24.42897 L -28.24232,24.23052
"""

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def norm(a):
    return math.hypot(*a)

def distance(a, b):
    return norm(sub(a, b))

def interpolate(a, b, t):
    return (a[0] + t * (b[0] - a[0]),
            a[1] + t * (b[1] - a[1]))

segments = []
previous = None
for command, x, y in re.findall(
        r"([ML])\s+(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)", path):
    point = (float(x), float(y))
    if command == "L":
        segments.append((previous, point))
    previous = point

# Split every segment at intersections, overlap endpoints, and near-coincident
# endpoints. This accounts for sides assembled from multiple SVG commands.
cuts = [[0.0, 1.0] for _ in segments]
for i, (a, b) in enumerate(segments):
    u = sub(b, a)
    length = norm(u)
    for c, d in segments:
        for p in (c, d):
            t = dot(sub(p, a), u) / dot(u, u)
            if -TOL / length <= t <= 1 + TOL / length:
                if distance(p, interpolate(a, b, t)) <= TOL:
                    cuts[i].append(max(0.0, min(1.0, t)))
        v = sub(d, c)
        denominator = cross(u, v)
        if abs(denominator) > 1e-10 * length * norm(v):
            t = cross(sub(c, a), v) / denominator
            s = cross(sub(c, a), u) / denominator
            if (0 <= t <= 1) and (0 <= s <= 1):
                cuts[i].append(t)

points = []
def vertex(p):
    for i, q in enumerate(points):
        if distance(p, q) <= TOL:
            return i
    points.append(p)
    return len(points) - 1

edges = set()
for (a, b), ts in zip(segments, cuts):
    ids = []
    for t in sorted(ts):
        k = vertex(interpolate(a, b, t))
        if not ids or ids[-1] != k:
            ids.append(k)
    for u, v in zip(ids, ids[1:]):
        if u != v:
            edges.add(tuple(sorted((u, v))))

adj = {i: set() for i in range(len(points))}
for a, b in edges:
    adj[a].add(b)
    adj[b].add(a)

# Edges outside the graph's 2-core cannot participate in any closed polygon.
queue = [v for v in adj if len(adj[v]) < 2]
while queue:
    v = queue.pop()
    for w in list(adj[v]):
        adj[w].remove(v)
        if len(adj[w]) == 1:
            queue.append(w)
    adj[v].clear()

def straight(a, b, c):
    u, v = sub(b, a), sub(c, b)
    return (dot(u, v) > 0 and
            abs(cross(u, v)) <= TOL * (norm(u) + norm(v)))

def simplify(poly):
    poly = list(poly)
    while len(poly) >= 3:
        for i in range(len(poly)):
            if straight(poly[i - 1], poly[i], poly[(i + 1) % len(poly)]):
                poly.pop(i)
                break
        else:
            return poly
    return poly

def orientation(a, b, c):
    return cross(sub(b, a), sub(c, a))

def simple_polygon(p):
    n = len(p)
    for i in range(n):
        a, b = p[i], p[(i + 1) % n]
        for j in range(i + 1, n):
            if j == i + 1 or (i == 0 and j == n - 1):
                continue
            c, d = p[j], p[(j + 1) % n]
            if (orientation(a, b, c) * orientation(a, b, d) < -1e-12 and
                    orientation(c, d, a) * orientation(c, d, b) < -1e-12):
                return False
    return True

def drawn_straight(a, b):
    u = sub(b, a)
    length = norm(u)
    intervals = []
    for c, d in segments:
        if (abs(cross(u, sub(c, a))) <= TOL * length and
                abs(cross(u, sub(d, a))) <= TOL * length):
            t, s = (dot(sub(p, a), u) / dot(u, u) for p in (c, d))
            lo, hi = max(0.0, min(t, s)), min(1.0, max(t, s))
            if hi >= lo:
                intervals.append((lo, hi))
    end = 0.0
    for lo, hi in sorted(intervals):
        if lo > end + TOL / length:
            return False
        end = max(end, hi)
    return end >= 1 - TOL / length

def has_diagonal(p):
    n = len(p)
    return any(drawn_straight(p[i], p[j])
               for i in range(n) for j in range(i + 2, n)
               if not (i == 0 and j == n - 1))

def parallel(u, v):
    return abs(cross(u, v)) <= TOL * (norm(u) + norm(v))

def perpendicular(u, v):
    return abs(dot(u, v)) <= TOL * (norm(u) + norm(v))

def classify(p):
    n = len(p)
    e = [sub(p[(i + 1) % n], p[i]) for i in range(n)]
    turns = [cross(e[i], e[(i + 1) % n]) for i in range(n)]
    convex = all(t > 0 for t in turns) or all(t < 0 for t in turns)
    right = [perpendicular(e[i], e[(i + 1) % n]) for i in range(n)]
    lengths = list(map(norm, e))
    equal_sides = max(lengths) - min(lengths) <= 4 * TOL
    angles = [math.atan2(abs(turns[i]), dot(e[i], e[(i + 1) % n]))
              for i in range(n)]
    regular = convex and equal_sides and max(angles) - min(angles) < 0.0002
    if n == 3:
        return 4 if any(right) else 3
    if n == 4 and convex:
        pairs = int(parallel(e[0], e[2])) + int(parallel(e[1], e[3]))
        if all(right):
            return 2 if equal_sides else 1
        if pairs == 2:
            return 5
        if pairs == 1:
            return 6
    if n == 5:
        return 9 if regular else (7 if convex else 8)
    if n == 6 and regular:
        return 10
    return None

# Exhaustive enumeration of undirected simple graph cycles:
# the start is the least vertex, and only one orientation is retained.
found = {}
cycle_count = 0

def inspect(cycle):
    global cycle_count
    cycle_count += 1
    p = simplify([points[v] for v in cycle])
    if len(p) < 3 or not simple_polygon(p):
        return
    k = classify(p)
    if k is None:
        return
    if k in (1, 2, 5, 6, 7, 8, 9, 10) and has_diagonal(p):
        return
    key = tuple(sorted((round(x, 5), round(y, 5)) for x, y in p))
    found.setdefault(k, {})[key] = p

def dfs(start, route, visited):
    last = route[-1]
    for nxt in adj[last]:
        if nxt == start:
            if len(route) >= 3 and route[1] < route[-1]:
                inspect(route)
        elif nxt > start and nxt not in visited:
            visited.add(nxt)
            route.append(nxt)
            dfs(start, route, visited)
            route.pop()
            visited.remove(nxt)

for start in sorted(adj):
    if adj[start]:
        dfs(start, [start], {start})

options = {
    "A": {5, 9}, "B": {5}, "C": {5, 7, 1}, "D": {5, 7, 3},
    "E": {5, 1, 2}, "F": {1, 4}, "G": {10}, "H": {7, 10},
    "I": {5, 7}, "J": {5, 1}, "K": {5, 7, 4, 6},
    "L": {8, 10}, "M": {7, 6}, "N": {7, 2, 8},
    "O": {7, 3}, "P": {5, 2, 6},
}
actual = set(found)
print("Exhaustively enumerated graph cycles:", cycle_count)
print("Detected shape numbers:", sorted(actual))
for k in sorted(found):
    print("Shape", k, "witness:",
          [(round(x, 5), round(y, 5)) for x, y in next(iter(found[k].values()))])
print("Matching options:", [letter for letter, content in options.items()
                            if content == actual])
print("Submitted J contains:", sorted(options["J"]))
print("CHECK PASS" if actual == options["J"] else "CHECK FAIL")
